insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('dph-hcp-note-101','Pharmacy','Diploma in Pharmacy','note','free',901,'{"title":"Introduction to Hospital Pharmacy and Pharmacy Services","english":"Hospital pharmacy is the department responsible for procurement, storage, preparation where authorized, distribution and safe use of medicines in a hospital. Its goals include ensuring medicine availability, quality, affordability and patient safety. Pharmacy services may include inpatient and outpatient dispensing, ward supply, sterile preparation in appropriate facilities, drug information, inventory control and participation in medication-safety activities. The pharmacist or pharmacy professional works with the healthcare team within their legal scope of practice.","nepali":"Hospital pharmacy भनेको अस्पतालमा औषधिको खरिद, भण्डारण, आवश्यक अनुमति भएको अवस्थामा तयारी, वितरण र सुरक्षित प्रयोगको जिम्मेवारी लिने विभाग हो। यसको उद्देश्य औषधिको उपलब्धता, गुणस्तर, पहुँचयोग्यता र बिरामीको सुरक्षा सुनिश्चित गर्नु हो। सेवामा inpatient तथा outpatient dispensing, ward supply, उपयुक्त facility मा sterile preparation, drug information, inventory control र medication safety गतिविधि पर्छन्। Pharmacy professional ले आफ्नो कानुनी कार्यक्षेत्रभित्र स्वास्थ्य टोलीसँग काम गर्छ।"}'::jsonb,true),
('dph-hcp-note-102','Pharmacy','Diploma in Pharmacy','note','free',902,'{"title":"Prescription Review and Dispensing Process","english":"A prescription should be checked for patient identity, date, prescriber details, medicine name, strength, dosage form, dose, route, frequency, duration and legibility. Assess possible duplication, allergy, interaction, contraindication and unusual dose; clarify uncertainty with the prescriber before dispensing. Select the correct product, calculate and label accurately, provide clear directions and document as required. Do not alter a prescription or provide restricted medicines outside applicable law and professional authority.","nepali":"Prescription जाँच्दा बिरामीको पहिचान, मिति, prescriber विवरण, औषधिको नाम, strength, dosage form, dose, route, frequency, duration र स्पष्टता हेर्नुपर्छ। दोहोरिएको औषधि, allergy, interaction, contraindication वा असामान्य dose शंका भए dispense गर्नुअघि prescriber सँग स्पष्ट गर्नुपर्छ। सही product छान्ने, सही हिसाब र label गर्ने, स्पष्ट निर्देशन दिने र आवश्यक अभिलेख राख्ने गर्नुपर्छ। लागू कानुन र आफ्नो अधिकारबाहिर prescription परिवर्तन वा restricted medicine वितरण गर्नु हुँदैन।"}'::jsonb,true),
('dph-hcp-note-103','Pharmacy','Diploma in Pharmacy','note','free',903,'{"title":"Hospital Drug Distribution Systems and Medication Safety","english":"Common hospital medicine distribution approaches include individual patient prescription orders, floor or ward stock and unit-dose systems. A unit-dose system supplies medicines in ready-to-administer, individually packaged doses and can support safer tracking when properly implemented. Medication safety uses checks such as the right patient, medicine, dose, route, time, documentation, indication and response. High-alert medicines, look-alike/sound-alike products and concentrated electrolytes require additional safeguards according to local policy.","nepali":"अस्पतालमा औषधि वितरणका सामान्य तरिकामा individual patient prescription order, floor वा ward stock र unit-dose system पर्छन्। Unit-dose system मा औषधि प्रत्येक dose का लागि छुट्टाछुट्टै तयार/pack गरिएको हुन्छ र सही रूपमा लागू गर्दा tracking तथा सुरक्षा बढाउन सक्छ। Medication safety मा सही बिरामी, औषधि, dose, route, समय, documentation, indication र response जाँचिन्छ। High-alert medicine, look-alike/sound-alike औषधि र concentrated electrolyte मा संस्थाको नीतिअनुसार थप सुरक्षा उपाय चाहिन्छ।"}'::jsonb,true),
('dph-hcp-note-104','Pharmacy','Diploma in Pharmacy','note','free',904,'{"title":"Clinical Pharmacy, Patient Counselling and Drug Information","english":"Clinical pharmacy focuses on optimizing medicine use and patient outcomes through collaboration with the healthcare team. Patient counselling should cover the medicine name and purpose, dose, route, timing, duration, administration technique, important precautions, common adverse effects, storage and what to do if a dose is missed, based on reliable product information. Use plain language and confirm understanding with teach-back. Drug information should be accurate, unbiased, current and referenced; refer clinical decisions to the authorized prescriber when required.","nepali":"Clinical pharmacy ले स्वास्थ्य टोलीसँग सहकार्य गरी औषधिको उचित प्रयोग र बिरामीको नतिजा सुधारमा ध्यान दिन्छ। बिरामीलाई औषधिको नाम र उद्देश्य, dose, route, समय, अवधि, प्रयोग गर्ने तरिका, सावधानी, सामान्य adverse effect, storage र dose छुटेमा के गर्ने भन्ने कुरा विश्वसनीय product information अनुसार बुझाउनुपर्छ। सरल भाषा प्रयोग गरी बिरामीलाई आफ्नै शब्दमा दोहोर्‍याउन लगाएर बुझाइ पुष्टि गर्नुपर्छ। Drug information सही, निष्पक्ष, अद्यावधिक र स्रोतसहित हुनुपर्छ; आवश्यक clinical निर्णय अधिकृत prescriber लाई पठाउनुपर्छ।"}'::jsonb,true),
('dph-hcp-note-105','Pharmacy','Diploma in Pharmacy','note','free',905,'{"title":"Hospital Inventory, Storage and Expiry Management","english":"Inventory management maintains adequate stock while minimizing shortages, overstocking, wastage and expiry. Common tools include stock records, reorder levels, lead-time review, physical counts and consumption-based forecasting. FEFO means first-expiry, first-out and is preferred for products with expiry dates; FIFO means first-in, first-out and may be used where appropriate. Store medicines under labeled manufacturer conditions, monitor temperature where required, secure controlled products and separate expired, damaged or recalled stock from usable inventory.","nepali":"Inventory management ले औषधिको अभाव, बढी stock, नोक्सानी र expiry घटाउँदै आवश्यक stock कायम राख्छ। Stock record, reorder level, lead-time review, physical count र खपतका आधारमा माग अनुमान गर्ने तरिका प्रयोग हुन्छ। FEFO भनेको पहिले expiry हुने औषधि पहिले निकाल्ने हो र expiry भएका सामानमा प्राथमिकता दिनुपर्छ; FIFO भनेको पहिले आएको सामान पहिले निकाल्ने हो। औषधि manufacturer ले तोकेको अवस्थामा राख्ने, आवश्यक तापक्रम निगरानी गर्ने, नियन्त्रित औषधि सुरक्षित राख्ने र expired, damaged वा recalled stock लाई प्रयोगयोग्य stock बाट अलग राख्नुपर्छ।"}'::jsonb,true),
('dph-hcp-mcq-101','Pharmacy','Diploma in Pharmacy','mcq','free',901,'{"question":"Which is a primary responsibility of a hospital pharmacy?","translation":"Hospital pharmacy को प्रमुख जिम्मेवारी कुन हो?","options":["Safe procurement, storage and distribution of medicines","Performing all surgeries","Diagnosing every disease","Replacing all prescribers"],"correctIndex":0,"explanation":"Hospital pharmacy supports medicine availability, quality and safe distribution and use.","explanationNe":"Hospital pharmacy ले औषधिको उपलब्धता, गुणस्तर, सुरक्षित वितरण र प्रयोगमा सहयोग गर्छ।"}'::jsonb,true),
('dph-hcp-mcq-102','Pharmacy','Diploma in Pharmacy','mcq','free',902,'{"question":"Which item should be checked when reviewing a prescription?","translation":"Prescription review गर्दा कुन कुरा जाँच्नुपर्छ?","options":["Patient identity and medicine dose","Patient's favourite colour","Only the paper size","The pharmacy wall colour"],"correctIndex":0,"explanation":"Patient identity, medicine, strength, dose, route and directions are core prescription checks.","explanationNe":"बिरामीको पहिचान, औषधि, strength, dose, route र निर्देशन prescription का मुख्य जाँच हुन्।"}'::json,true),
('dph-hcp-mcq-103','Pharmacy','Diploma in Pharmacy','mcq','free',903,'{"question":"FEFO stands for:","translation":"FEFO को पूरा रूप के हो?","options":["First Entered, First Ordered","First Expiry, First Out","Final Entry, Final Order","Fast Evaluation For Output"],"correctIndex":1,"explanation":"FEFO means products with the earliest expiry date are issued first.","explanationNe":"FEFO मा सबैभन्दा पहिले expiry हुने product पहिले वितरण गरिन्छ।"}'::jsonb,true),
('dph-hcp-mcq-104','Pharmacy','Diploma in Pharmacy','mcq','free',904,'{"question":"What should be done if a prescription contains an unclear or potentially unsafe dose?","translation":"Prescription मा dose अस्पष्ट वा सम्भावित रूपमा असुरक्षित भए के गर्नुपर्छ?","options":["Guess the dose","Clarify with the prescriber before dispensing","Ignore the dose","Ask another patient"],"correctIndex":1,"explanation":"Unclear or potentially unsafe orders must be clarified with the authorized prescriber before dispensing.","explanationNe":"अस्पष्ट वा असुरक्षित हुन सक्ने order dispense गर्नुअघि अधिकृत prescriber सँग स्पष्ट गर्नुपर्छ।"}'::jsonb,true),
('dph-hcp-mcq-105','Pharmacy','Diploma in Pharmacy','mcq','free',905,'{"question":"A unit-dose distribution system generally provides medicines as:","translation":"Unit-dose distribution system मा औषधि कसरी उपलब्ध गराइन्छ?","options":["Individually packaged doses","Unlabeled mixed containers","Only bulk raw materials","Unrecorded ward supplies"],"correctIndex":0,"explanation":"Unit-dose systems provide individually packaged doses intended for a single administration.","explanationNe":"Unit-dose system मा एक पटकको प्रयोगका लागि छुट्टाछुट्टै dose pack गरी दिइन्छ।"}'::jsonb,true),
('dph-hcp-mcq-106','Pharmacy','Diploma in Pharmacy','mcq','free',906,'{"question":"Which method prioritizes medicines with the earliest expiry date?","translation":"सबैभन्दा पहिले expiry हुने औषधिलाई प्राथमिकता दिने विधि कुन हो?","options":["FIFO","FEFO","LIFO","ABC only"],"correctIndex":1,"explanation":"FEFO (First Expiry, First Out) prioritizes the earliest-expiring stock.","explanationNe":"FEFO (First Expiry, First Out) ले पहिले expiry हुने stock पहिले निकाल्छ।"}'::jsonb,true),
('dph-hcp-mcq-107','Pharmacy','Diploma in Pharmacy','mcq','free',907,'{"question":"Which is an appropriate counselling technique to confirm patient understanding?","translation":"बिरामीले कुरा बुझेको पुष्टि गर्ने उपयुक्त counselling तरिका कुन हो?","options":["Teach-back","Speaking faster","Using unexplained abbreviations","Avoiding questions"],"correctIndex":0,"explanation":"Teach-back asks the patient to explain instructions in their own words.","explanationNe":"Teach-back मा बिरामीलाई निर्देशन आफ्नै शब्दमा भन्न लगाएर बुझाइ पुष्टि गरिन्छ।"}'::jsonb,true),
('dph-hcp-mcq-108','Pharmacy','Diploma in Pharmacy','mcq','free',908,'{"question":"Look-alike/sound-alike medicines require:","translation":"Look-alike/sound-alike औषधिका लागि के आवश्यक हुन्छ?","options":["Additional safeguards","No labeling","Storage together without separation","Removal of expiry dates"],"correctIndex":0,"explanation":"Additional safeguards such as clear separation, labeling and independent checks can reduce selection errors.","explanationNe":"स्पष्ट separation, labeling र independent check जस्ता थप सावधानीले गलत औषधि छान्ने जोखिम घटाउँछन्।"}'::jsonb,true),
('dph-hcp-mcq-109','Pharmacy','Diploma in Pharmacy','mcq','free',909,'{"question":"Which stock should be separated from usable medicines?","translation":"कुन stock लाई प्रयोगयोग्य औषधिबाट अलग राख्नुपर्छ?","options":["Expired or recalled products","Newly received valid stock","Correctly stored stock","Products within expiry"],"correctIndex":0,"explanation":"Expired, damaged or recalled medicines must be segregated and managed under policy.","explanationNe":"Expired, damaged वा recalled औषधिलाई अलग राखेर संस्थाको नीतिअनुसार व्यवस्थापन गर्नुपर्छ।"}'::jsonb,true),
('dph-hcp-mcq-110','Pharmacy','Diploma in Pharmacy','mcq','free',910,'{"question":"Clinical pharmacy primarily aims to:","translation":"Clinical pharmacy को मुख्य उद्देश्य के हो?","options":["Optimize medicine use and patient outcomes","Increase medicine wastage","Avoid communication with clinicians","Replace laboratory services"],"correctIndex":0,"explanation":"Clinical pharmacy promotes safe, effective and appropriate medicine use for better patient outcomes.","explanationNe":"Clinical pharmacy ले बिरामीको राम्रो नतिजाका लागि औषधिको सुरक्षित, प्रभावकारी र उचित प्रयोग बढाउँछ।"}'::jsonb,true),
('dph-hcp-mock-101','Pharmacy','Diploma in Pharmacy','mock','free',1001,'{"question":"List five important checks when reviewing a prescription before dispensing.","answer":"Check patient identity, date and prescriber details, medicine name and strength, dosage form, dose, route, frequency, duration, legibility, allergies and possible interactions or contraindications.","answerNe":"बिरामीको पहिचान, मिति र prescriber विवरण, औषधिको नाम र strength, dosage form, dose, route, frequency, duration, स्पष्टता, allergy तथा सम्भावित interaction वा contraindication जाँच्नुपर्छ।"}'::jsonb,true),
('dph-hcp-mock-102','Pharmacy','Diploma in Pharmacy','mock','free',1002,'{"question":"Differentiate FIFO and FEFO in medicine inventory management.","answer":"FIFO issues stock received first first. FEFO issues stock with the earliest expiry date first and is especially important for medicines with expiry dates.","answerNe":"FIFO मा पहिले आएको stock पहिले वितरण हुन्छ। FEFO मा पहिले expiry हुने stock पहिले वितरण हुन्छ र expiry भएका औषधिमा यो विशेष महत्त्वपूर्ण हुन्छ।"}'::jsonb,true),
('dph-hcp-mock-103','Pharmacy','Diploma in Pharmacy','mock','free',1003,'{"question":"What is a unit-dose distribution system? State one potential safety benefit.","answer":"Medicines are supplied in individually packaged doses for a single administration. It can improve dose identification and tracking and reduce some selection or preparation errors when properly implemented.","answerNe":"एक पटकको administration का लागि औषधि छुट्टाछुट्टै dose pack गरी उपलब्ध गराइन्छ। सही रूपमा लागू गर्दा dose पहिचान र tracking सुधारेर केही selection वा preparation error घटाउन सक्छ।"}'::jsonb,true),
('dph-hcp-mock-104','Pharmacy','Diploma in Pharmacy','mock','free',1004,'{"question":"Outline key points to include in patient counselling for a dispensed medicine.","answer":"Explain the medicine name and purpose, dose, route, timing, duration, administration technique, important precautions, common adverse effects, storage and missed-dose advice using reliable product information. Confirm understanding with teach-back.","answerNe":"विश्वसनीय product information अनुसार औषधिको नाम र उद्देश्य, dose, route, समय, अवधि, प्रयोग विधि, सावधानी, सामान्य adverse effect, storage र dose छुटेमा के गर्ने बुझाउनुहोस्। Teach-back बाट बुझाइ पुष्टि गर्नुहोस्।"}'::jsonb,true),
('dph-hcp-mock-105','Pharmacy','Diploma in Pharmacy','mock','free',1005,'{"question":"Mention five good practices for hospital medicine storage and inventory control.","answer":"Maintain stock records and reorder levels, use FEFO, follow manufacturer storage conditions, monitor temperature where required, secure controlled medicines, and segregate expired, damaged or recalled products.","answerNe":"Stock record र reorder level राख्ने, FEFO अपनाउने, manufacturer ले तोकेको storage condition पालना गर्ने, आवश्यक तापक्रम निगरानी गर्ने, controlled medicine सुरक्षित राख्ने र expired, damaged वा recalled सामान अलग राख्ने।"}'::jsonb,true)
